class Solution {
public:
    int xorBeauty(std::vector<int>& nums) {
        int ans = 0;
        for (int x : nums) ans ^= x;
        return ans;
    }
};

class Solution {
    public int xorBeauty(int[] nums) {
        int ans = 0;
        for (int x : nums) ans ^= x;
        return ans;
    }
}

var xorBeauty = function(nums) {
    let ans = 0;
    for (const x of nums) ans ^= x;
    return ans;
};
